import{z as A,x as l,o as E,c as s,q as r,j as o,D as e,d as i,s as n,S as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"汇率风险的溢价","description":"","frontmatter":{"title":"汇率风险的溢价","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/if-fx-risk-premia.md","filePath":"econ/if-fx-risk-premia.md","lastUpdated":1791413859000}'),p={name:"econ/if-fx-risk-premia.md"};function m(d,a,_,f,h,C){const t=l("Mermaid");return E(),s("div",null,[a[2]||(a[2]=r('<h1 id="汇率风险的溢价" tabindex="-1">汇率风险的溢价 <a class="header-anchor" href="#汇率风险的溢价" aria-label="Permalink to &quot;汇率风险的溢价&quot;">​</a></h1><div class="epigraph"><p>无抛补平价把利率差读成预期贬值；把它拆开，剩下那半是风险的价格，而这个价格由中介资产负债表的松紧来定——溢价不是噪声，是全球金融体系收的保费。</p><footer>—— 据 Fama, JME 1984；Lustig, Roussanov and Verdelhan, RFS 2011；Gabaix and Maggiori, QJE 2015 整理</footer></div><p><a href="/econ/gd-map">上一课</a>把增长与发展的深化收在激励与制度上：微观楔子与宏观渠道在激励结构汇合，制度是否可改变是留下的问题。增长的故事走到国界处换主角——资本跨国流动、汇率定价、美元周期；本课程「国际金融深化」从价格侧开工。既成的起点是中心货币：<a href="/econ/dollar-dominance">美元主导与国际货币</a>给出了计价、跨境银行负债与官方地板的三层捆绑，浮动汇率取消不了 Rey 意义上的全球金融周期；主干<a href="/econ/forward-premium-puzzle">远期溢价之谜</a>则给出事实——Fama 回归的斜率常为负、高息货币平均升值。本课的缺口是负斜率的<strong>来源</strong>：预期错在哪、溢价怎么被定价、为什么它随全球周期同涨同落。本课程之后依次写跨境银行与美元周期、资本流动的驱动，再过外汇干预与资本管制两课政策，最后收束。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记本币与外币的利率差为 \\(fp_t = i_t - i_t^*\\)，UIP 说 \\(E_t \\Delta s_{t+1} = fp_t\\)。把远期溢价拆成两块：</p> \\[fp_t = E_t \\Delta s_{t+1} + rp_t, \\]<p>其中 \\(rp_t\\) 是风险溢价。若 UIP 成立且预期理性，\\(\\Delta s_{t+1}\\) 对 \\(fp_t\\) 回归的斜率应是 1；实证斜率远低于 1 且常为负，要求</p> \\[\\mathrm{Cov}(rp_t, fp_t) \\gt \\mathrm{Var}(fp_t): \\]<p>溢价的摆幅必须<strong>超过</strong>远期溢价自身。缺口因此不是「UIP 又失败了」——预期误差填不满这个坑——而是：\\(rp_t\\) 由什么定价，它为什么在高息货币上长期为负，又在什么时刻突然转正。</p><h3 id="溢价的定价" tabindex="-1">溢价的定价 <a class="header-anchor" href="#溢价的定价" aria-label="Permalink to &quot;溢价的定价&quot;">​</a></h3><p>证据分三层。横截面上，按远期溢价排序的货币组合能被两个因子定价：美元因子与斜率因子（Lustig–Roussanov–Verdelhan 2011）——套息收益不是逐对货币的特例，是一个共同的斜率风险在收费。时间序列上，套息策略收益高度负偏：赚钱细水长流，亏钱集中在崩断（Brunnermeier–Nagel–Pedersen 2009），高息货币恰在全球避险时急贬。结构上，汇率由中介资产负债表的容量决定（Gabaix–Maggiori 2015）：中介吸收币种错配，容量紧时风险价格上升。</p><p><span class="marginnote">Fama 自己对 1980 年代主要货币的估计斜率低到 −3 上下，此后 G10 月度回归的常见读数落在 −1 与 −3 之间。斜率为负意味着 \\(\\mathrm{Cov}(rp,fp)\\) 的正值超过 \\(\\mathrm{Var}(fp)\\)——预期误差解释不了这么大的摆幅；Froot 与 Frankel（1989）用调查预期把预期与溢价分开后，主导的一侧仍是溢价。</span></p><p><span class="marginnote">「套息交易」（carry trade）直译过来就是「赚息差」：借利率低的货币（比如日元），换成利率高的货币（比如澳元）去投资，汇率不动就白赚利差。它是本章的主角——高息货币平均升值、套息还倒赚，正说明风险溢价在给「借低投高」的敞口让渡保费。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测法分四步。第一步写清分解：\\(\\beta = 1 - \\mathrm{Cov}(rp,fp)/\\mathrm{Var}(fp)\\)，先算协方差再谈解释——不分解就直接把负斜率读成「市场无效」，是把风险的价格当成白捡的钱。第二步分开预期与溢价：调查预期或事后实现均值单独量 \\(E_t\\Delta s_{t+1}\\)，剩下归 \\(rp\\)。第三步做结构检验：组合排序看因子载荷，事件窗口看中介变量（VIX、交易商杠杆）与溢价是否同动。第四步接回全球周期：美元升值与中介缩表正是溢价走阔的同一件事，这条线本课程后面反复出现。</p>',15)),(E(),o(B,null,{default:e(()=>[n(t,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20FP%5B%22%E8%BF%9C%E6%9C%9F%E6%BA%A2%E4%BB%B7%20fp%20%3D%20i%20%E2%88%92%20i*%22%5D%20--%3E%20EXP%5B%22%E9%A2%84%E6%9C%9F%E8%B4%AC%E5%80%BC%20E%20%CE%94s%22%5D%0A%20%20FP%20--%3E%20RP%5B%22%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%20rp%22%5D%0A%20%20RP%20--%3E%20CRASH%5B%22%E5%B4%A9%E6%96%AD%E9%A3%8E%E9%99%A9%3A%20%E8%B4%9F%E5%81%8F%E5%BA%A6%22%5D%0A%20%20RP%20--%3E%20CAP%5B%22%E4%B8%AD%E4%BB%8B%E5%AE%B9%E9%87%8F%3A%20VIX%20%E4%B8%8E%E7%BE%8E%E5%85%83%22%5D%0A%20%20CRASH%20--%3E%20NEG%5B%22Fama%20%E6%96%9C%E7%8E%87%E8%BF%9C%E4%BD%8E%E4%BA%8E%201%22%5D%0A%20%20CAP%20--%3E%20NEG%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把外汇当成一张保险单。套息交易等于卖出美元融资压力的保险：平时收权利金（利率差），美元荒时一次性赔付；负偏度不是异常，是保单的形状。中介机制解释溢价为什么在<strong>所有</strong>货币对上同时动：中介资本是全局稀缺品，VIX 上升、美元升值时，同一份资本要背所有币种错配，保费集体上浮。这正好接上<a href="/econ/global-financial-cycle">全球金融周期</a>：中心风险偏好经中介容量，把外围的汇率风险溢价焊在一起。三个常见错误随之排除：把崩断月的亏损当「可忽略的小概率」（它就是策略的保险成本）；把溢价走阔当必须救助的「失灵」（它是风险的价格，救不救是分配问题不是测度问题）；把 CIP 基差与风险溢价混写——基差是中介约束的会计价格，见<a href="/quant/irp">量化栏的利率平价</a>，不承担预期假说。</p><p><span class="marginnote">数字实例：日元利率 0.5%、澳元利率 5%，借 100 万日元换成澳元存一年，汇率不动就赚 4.5% 利差；可只要日元那年升值超过 4.5%，利差就全部赔光——2008 年 10 月套息平仓让日元单月对澳元升值近三成，等于多年权利金一次赔穿。</span></p>',3)),(E(),o(B,null,{default:e(()=>[n(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOR%5B%22%E5%80%9F%E4%BD%8E%E6%81%AF%E8%B4%A7%E5%B8%81%20%E6%8A%95%E9%AB%98%E6%81%AF%E8%B4%A7%E5%B8%81%22%5D%20--%3E%20CALM%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%3A%20%E7%BB%86%E6%B0%B4%E9%95%BF%E6%B5%81%E6%94%B6%E5%88%A9%E5%B7%AE%22%5D%0A%20%20CALM%20--%3E%20SHOCK%7B%22%E5%85%A8%E7%90%83%E9%81%BF%E9%99%A9%E4%BA%8B%E4%BB%B6%22%7D%0A%20%20SHOCK%20--%3E%7C%22%E5%A4%9A%E6%95%B0%E6%97%B6%E5%80%99%22%7C%20CALM%0A%20%20SHOCK%20--%3E%7C%22%E5%B0%91%E6%95%B0%E6%97%B6%E5%80%99%22%7C%20CRASH%5B%22%E9%AB%98%E6%81%AF%E8%B4%A7%E5%B8%81%E6%80%A5%E8%B4%AC%3A%20%E4%B8%80%E6%AC%A1%E6%80%A7%E5%A4%A7%E4%BA%8F%22%5D%0A%20%20CRASH%20--%3E%20CAP%5B%22%E4%B8%AD%E4%BB%8B%E8%B5%84%E6%9C%AC%E5%8F%97%E6%8D%9F%20%E5%AE%B9%E9%87%8F%E6%94%B6%E7%B4%A7%22%5D%0A%20%20CAP%20--%3E%20PREM%5B%22%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%E9%9B%86%E4%BD%93%E4%B8%8A%E6%B5%AE%22%5D%0A%20%20PREM%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E8%A6%81%E6%B1%82%E7%9A%84%E8%A1%A5%E5%81%BF%E6%9B%B4%E9%AB%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不宣称负斜率已被完全解释：预期误差、比索问题与溢价的纠缠仍在，样本与频率都敏感（Engel 2016 表明溢价解释不完样本期）。也不把溢价写成可套取的工程量：策略收益对交易成本、容量与崩断风险高度敏感，量化栏的<a href="/quant/fx-carry-mom">外汇套息与动量</a>管那半边。溢价是风险的影子价格，不直接给出政策方向；把它接到数量侧——美元信贷如何随中介周期进退——是下一课的事。</p><p><span class="marginnote">「比索问题」是名称很怪的经典陷阱：1970 年代墨西哥比索盯住美元，多数时间汇率纹丝不动，回归看起来很稳，其实市场一直在为罕见的大贬值定价。初学者容易把「样本里没出事」当成「预期错了」，实际上可能只是那件小概率大事还没轮到——负 Fama 斜率的一部分纠缠正来源于此。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>远期溢价 \\(=\\) 预期贬值 \\(+\\) 风险溢价；负 Fama 斜率要求 \\(\\mathrm{Cov}(rp,fp) \\gt \\mathrm{Var}(fp)\\)。</li><li>溢价由共同因子定价：美元因子与斜率因子；崩断的负偏度是保单的形状。</li><li>结构机制是中介容量：VIX 与美元紧缩使保费集体上浮，接上全球金融周期。</li><li>CIP 基差与 UIP 溢价是两件事，不要混写。</li><li>出处：Fama, <em>JME</em> 1984；Froot–Frankel, <em>QJE</em> 1989；Lustig–Roussanov–Verdelhan, <em>RFS</em> 2011；Brunnermeier–Nagel–Pedersen, <em>NBER Macro Annual</em> 2009；Gabaix–Maggiori, <em>QJE</em> 2015。</li></ul>',5))])}const P=A(p,[["render",m]]);export{u as __pageData,P as default};
